// Works out what the shopkeeper wants (from a tapped list/button or typed text)
// and which products to fetch.
const PAGE = 7;
const msg = $('Extract Message').first().json;
const ctx = $input.first().json;
const raw = String(msg.text || '').trim().slice(0, 200);
const text = raw.toLowerCase().replace(/\s+/g, ' ').replace(/[.!]+$/, '');
const rid = String(msg.replyId || '');
const state = ctx.state || 'IDLE';

let items = [];
let view = { mode: 'categories', category: '', q: '', page: 1, total: 0, catPage: 1, catPages: 1 };
const stored = ctx.cart;
if (Array.isArray(stored)) {
  items = stored;
} else if (stored && typeof stored === 'object') {
  items = Array.isArray(stored.items) ? stored.items : [];
  if (stored.view && typeof stored.view === 'object') view = Object.assign(view, stored.view);
}
const currentProduct = ctx.current_product_id ? String(ctx.current_product_id) : '';
const lastPage = Math.max(1, Math.ceil((Number(view.total) || 0) / PAGE));

const r = { cmd: 'help', mode: 'categories', category: '', q: '', page: 1, catPage: 1, productId: '', qty: null, editPage: 1, reset: false, note: '' };

const showView = (page, catPage) => {
  r.cmd = 'list';
  r.mode = view.mode || 'categories';
  r.category = view.category || '';
  r.q = view.q || '';
  r.page = Math.min(Math.max(1, page || 1), lastPage);
  r.catPage = Math.min(Math.max(1, catPage || view.catPage || 1), Math.max(1, view.catPages || 1));
};
const categories = (catPage) => { r.cmd = 'list'; r.mode = 'categories'; r.catPage = Math.max(1, catPage || 1); };

const startWords = ['order', 'hi', 'hello', 'hey', 'menu', 'start', 'products', 'list', 'categories', 'category', 'all'];
const newOrderWords = ['new order', 'restart'];
const cancelWords = ['cancel', 'stop'];
const nextWords = ['next', 'more', 'next page', '>'];
const backWords = ['back', 'prev', 'previous', 'previous page', '<'];
const cartWords = ['cart', 'view cart', 'my cart', 'done', 'checkout', 'review', 'finish'];
const confirmWords = ['confirm', 'yes', 'ok', 'place order', 'confirm order'];

if (!ctx.shopkeeper_id) {
  r.cmd = 'unregistered';
} else if (ctx.last_message_id && ctx.last_message_id === msg.messageId) {
  r.cmd = 'skip';
} else if (rid) {
  // ids look like kind|a|b
  const parts = rid.split('|');
  const kind = parts[0];
  const a = parts[1] || '';
  const rest = parts.slice(2).join('|');
  if (kind === 'menu') categories(parseInt(a, 10) || 1);
  else if (kind === 'cat') { r.cmd = 'list'; r.mode = 'category'; r.page = parseInt(a, 10) || 1; r.category = rest; }
  else if (kind === 'search') { r.cmd = 'list'; r.mode = 'search'; r.page = parseInt(a, 10) || 1; r.q = rest; }
  else if (kind === 'prod') { r.cmd = 'product'; r.productId = a; }
  else if (kind === 'qty') { r.cmd = 'setqty'; r.productId = a; r.qty = parseFloat(rest); }
  else if (kind === 'back') showView(view.page);
  else if (kind === 'cart') r.cmd = 'cart';
  else if (kind === 'edit') { r.cmd = 'editcart'; r.editPage = parseInt(a, 10) || 1; }
  else if (kind === 'confirm') r.cmd = state === 'REVIEWING_ORDER' ? 'confirm' : 'cart';
  else if (kind === 'cancel') r.cmd = 'cancel';
  else categories(1);
} else if (cancelWords.includes(text)) {
  r.cmd = 'cancel';
} else if (newOrderWords.includes(text)) {
  categories(1); r.reset = true;
} else if (startWords.includes(text)) {
  categories(1);
  if (state === 'IDLE') r.reset = true;
} else if (state === 'IDLE') {
  r.cmd = 'help';
} else if (state === 'ENTERING_QUANTITY' && currentProduct && /^\d+(\.\d+)?$/.test(text)) {
  r.cmd = 'setqty'; r.productId = currentProduct; r.qty = parseFloat(text);
} else if (state === 'ENTERING_QUANTITY' && currentProduct && ['remove', 'delete'].includes(text)) {
  r.cmd = 'setqty'; r.productId = currentProduct; r.qty = 0;
} else if (nextWords.includes(text)) {
  if (view.mode === 'categories') showView(1, (view.catPage || 1) + 1);
  else { if ((view.page || 1) >= lastPage) r.note = 'You are already on the last page.'; showView((view.page || 1) + 1); }
} else if (backWords.includes(text)) {
  if (state === 'ENTERING_QUANTITY' || state === 'REVIEWING_ORDER') showView(view.page);
  else if (view.mode === 'categories') showView(1, (view.catPage || 1) - 1);
  else if ((view.page || 1) <= 1) categories(view.catPage || 1);
  else showView((view.page || 1) - 1);
} else if (cartWords.includes(text)) {
  r.cmd = 'cart';
} else if (confirmWords.includes(text)) {
  r.cmd = state === 'REVIEWING_ORDER' ? 'confirm' : 'cart';
} else if (/^\d+(\.\d+)?$/.test(text)) {
  r.cmd = 'list'; r.mode = view.mode || 'categories'; r.category = view.category || ''; r.q = view.q || ''; r.page = view.page || 1; r.catPage = view.catPage || 1;
  r.note = 'To set a quantity, first tap a product from the list.';
} else {
  r.cmd = 'list'; r.mode = 'search'; r.page = 1;
  r.q = raw.replace(/^(search|find)\s+/i, '').replace(/[%_\\|]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 40);
}

if (r.reset) items = [];

const listMode = r.cmd === 'list' && r.mode !== 'categories';
return [{ json: Object.assign(r, {
  limit: PAGE,
  offset: listMode ? (r.page - 1) * PAGE : 0,
  qCategory: listMode && r.mode === 'category' ? r.category : '',
  qSearch: listMode && r.mode === 'search' ? r.q : '',
  state, items, view, currentProduct,
}) }];

// Builds the WhatsApp Cloud API message (tappable list, product card with image, or buttons).
const PAGE = 7;
const MAX_CART_LINES = 50;
const MAX_QTY = 10000;

const msg = $('Extract Message').first().json;
const ctx = $('Load Shopkeeper & Session').first().json;
const it = $('Parse Intent').first().json;
const res = $input.first().json || {};

const products = Array.isArray(res.products) ? res.products : [];
const cats = Array.isArray(res.categories) ? res.categories : [];
const total = Number(res.total || 0);
const product = res.product && res.product.id ? res.product : null;
const listPageNo = res.page_offset != null ? Math.floor(Number(res.page_offset) / PAGE) + 1 : null;

const money = (n) => 'Rs. ' + Number(n || 0).toFixed(Number(n) % 1 ? 2 : 0);
const round2 = (n) => Math.round(n * 100) / 100;
const cut = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const name = ctx.owner_name || ctx.shop_name || '';

let items = Array.isArray(it.items) ? it.items.slice() : [];
let view = Object.assign({ mode: 'categories', category: '', q: '', page: 1, total: 0, catPage: 1, catPages: 1 }, it.view || {});
let state = it.state || 'IDLE';
let currentProductId = null;

const out = {
  action: 'reply', reply: '', outMessage: null, state: state, sessionCart: null, currentProductId: null,
  orderItems: [], total: 0, invoiceBody: '',
  shopkeeperId: ctx.shopkeeper_id || null, distributorId: ctx.distributor_id || null,
  ownerName: ctx.owner_name || '', shopName: ctx.shop_name || '',
  distributorName: ctx.distributor_name || 'your distributor',
  distributorWhatsapp: ctx.distributor_whatsapp ? String(ctx.distributor_whatsapp) : '',
  from: msg.from, phoneNumberId: msg.phoneNumberId, messageId: msg.messageId,
};

const cartTotal = () => round2(items.reduce((s, i) => s + Number(i.line_total || 0), 0));
const cartLine = () => items.length ? '🛒 Cart: ' + items.length + ' item(s) · ' + money(cartTotal()) : '🛒 Cart is empty';
const inCart = (id) => items.find((i) => String(i.product_id) === String(id));

// ---- message builders (WhatsApp limits: body 1024, row title 24, row desc 72, button 20, max 10 rows / 3 buttons)
const base = () => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to: msg.from });
const text = (body) => Object.assign(base(), { type: 'text', text: { preview_url: false, body: cut(body, 4000) } });
const list = (header, body, button, rows, footer) => Object.assign(base(), {
  type: 'interactive',
  interactive: {
    type: 'list',
    header: { type: 'text', text: cut(header, 60) },
    body: { text: cut(body, 1024) },
    footer: { text: cut(footer || 'Type a product name to search', 60) },
    action: { button: cut(button, 20), sections: [{ title: cut(header, 24), rows: rows.slice(0, 10).map((r) => ({ id: cut(r.id, 200), title: cut(r.title, 24), description: cut(r.description || '', 72) })) }] },
  },
});
const buttons = (body, btns, imageUrl, footer) => {
  const m = Object.assign(base(), {
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: cut(body, 1024) },
      action: { buttons: btns.slice(0, 3).map((b) => ({ type: 'reply', reply: { id: cut(b.id, 256), title: cut(b.title, 20) } })) },
    },
  });
  if (imageUrl) m.interactive.header = { type: 'image', image: { link: imageUrl } };
  if (footer) m.interactive.footer = { text: cut(footer, 60) };
  return m;
};

// ---- screens
const categoriesScreen = (prefix) => {
  state = cats.length ? 'SELECTING_PRODUCT' : 'IDLE';
  if (!cats.length) return text('Sorry, no products are available right now. Please try again later.');
  const cartRow = items.length ? 1 : 0;
  const capacity = 10 - cartRow;
  const perPage = cats.length <= capacity ? capacity : 7;
  const catPages = Math.max(1, Math.ceil(cats.length / perPage));
  const catPage = Math.min(Math.max(1, it.catPage || 1), catPages);
  view = Object.assign(view, { mode: 'categories', category: '', q: '', page: 1, total: 0, catPage: catPage, catPages: catPages });
  const rows = cats.slice((catPage - 1) * perPage, catPage * perPage)
    .map((c) => ({ id: 'cat|1|' + c.name, title: c.name, description: c.count + ' products' }));
  if (catPage < catPages) rows.push({ id: 'menu|' + (catPage + 1), title: '➡️ More categories', description: 'Page ' + (catPage + 1) + ' of ' + catPages });
  if (catPage > 1) rows.push({ id: 'menu|' + (catPage - 1), title: '⬅️ Previous categories', description: '' });
  if (cartRow) rows.push({ id: 'cart', title: '🛒 View cart', description: items.length + ' item(s) · ' + money(cartTotal()) });
  const body = (prefix ? prefix + '\n\n' : '') + '👋 Hello ' + name + '!\n\nTap *Browse* to pick a category, or just type a product name (e.g. _maggi_, _atta_) to search.' + (items.length ? '\n\n' + cartLine() : '');
  return list('Shop by category', body, 'Browse', rows);
};

const productListScreen = (prefix) => {
  const label = it.mode === 'search' ? 'Search: ' + it.q : it.category;
  if (total === 0) {
    state = 'SELECTING_PRODUCT';
    return buttons((prefix ? prefix + '\n\n' : '') + 'No products found for "' + (it.q || it.category) + '". Try another name, or browse categories.',
      [{ id: 'menu|1', title: '📂 Categories' }].concat(items.length ? [{ id: 'cart', title: '🛒 View cart' }] : []));
  }
  const pages = Math.max(1, Math.ceil(total / PAGE));
  const page = Math.min(Math.max(1, listPageNo || it.page || 1), pages);
  state = 'SELECTING_PRODUCT';
  view = Object.assign(view, { mode: it.mode, category: it.category || '', q: it.q || '', page: page, total: total });
  const key = it.mode === 'search' ? 'search|' : 'cat|';
  const val = it.mode === 'search' ? it.q : it.category;
  const rows = products.map((p) => {
    const c = inCart(p.id);
    return { id: 'prod|' + p.id, title: p.name, description: money(p.price) + '/' + (p.unit || 'Piece') + (c ? ' · ✅ ' + c.qty + ' in cart' : (p.description ? ' · ' + p.description : '')) };
  });
  if (page < pages) rows.push({ id: key + (page + 1) + '|' + val, title: '➡️ Next page', description: 'Page ' + (page + 1) + ' of ' + pages });
  if (page > 1) rows.push({ id: key + (page - 1) + '|' + val, title: '⬅️ Previous page', description: '' });
  else rows.push({ id: 'menu|' + (view.catPage || 1), title: '📂 All categories', description: '' });
  if (items.length) rows.push({ id: 'cart', title: '🛒 View cart', description: items.length + ' item(s) · ' + money(cartTotal()) });
  const body = (prefix ? prefix + '\n\n' : '') + '*' + label + '* — ' + total + ' products (page ' + page + ' of ' + pages + ')\n\nTap *View products* and choose an item to see its photo and add it.' + (items.length ? '\n\n' + cartLine() : '');
  return list(cut(label, 60), body, 'View products', rows);
};

const productScreen = () => {
  if (!product) { state = 'SELECTING_PRODUCT'; return text('Sorry, that product is no longer available. Send ORDER to browse again.'); }
  state = 'ENTERING_QUANTITY';
  currentProductId = product.id;
  const c = inCart(product.id);
  const body = '*' + product.name + '*\n' + (product.description ? product.description + '\n' : '') +
    '\n💰 ' + money(product.price) + ' per ' + (product.unit || 'Piece') +
    (c ? '\n✅ In cart: ' + c.qty + ' (' + money(c.line_total) + ')' : '') +
    '\n\nTap a quantity, or *type any number* (e.g. 24).';
  const btns = c
    ? [{ id: 'qty|' + product.id + '|6', title: 'Set 6' }, { id: 'qty|' + product.id + '|12', title: 'Set 12' }, { id: 'qty|' + product.id + '|0', title: '🗑 Remove' }]
    : [{ id: 'qty|' + product.id + '|1', title: 'Add 1' }, { id: 'qty|' + product.id + '|6', title: 'Add 6' }, { id: 'qty|' + product.id + '|12', title: 'Add 12' }];
  return buttons(body, btns, product.image_url || '', 'Type BACK for the list · CART to review');
};

const cartScreen = (prefix) => {
  if (!items.length) {
    state = 'SELECTING_PRODUCT';
    return buttons((prefix ? prefix + '\n\n' : '') + '🛒 Your cart is empty.', [{ id: 'menu|1', title: '📂 Categories' }]);
  }
  state = 'REVIEWING_ORDER';
  const lines = items.map((i, n) => (n + 1) + '. ' + i.name + '\n    ' + i.qty + ' × ' + money(i.unit_price) + ' = *' + money(i.line_total) + '*');
  let shown = lines.join('\n');
  if (shown.length > 800) {
    let acc = ''; let k = 0;
    while (k < lines.length && (acc + lines[k]).length < 760) { acc += lines[k] + '\n'; k++; }
    shown = acc + '…and ' + (lines.length - k) + ' more item(s)';
  }
  const body = (prefix ? prefix + '\n\n' : '') + '🧾 *Your order*\n\n' + shown + '\n\n*Total: ' + money(cartTotal()) + '* (' + items.length + ' items)';
  return buttons(body, [{ id: 'confirm', title: '✅ Confirm order' }, { id: 'edit|1', title: '✏️ Edit cart' }, { id: 'back', title: '➕ Add more' }], '', 'Type CANCEL to discard this order');
};

const editCartScreen = () => {
  if (!items.length) return cartScreen();
  state = 'REVIEWING_ORDER';
  const pages = Math.max(1, Math.ceil(items.length / 8));
  const page = Math.min(Math.max(1, it.editPage || 1), pages);
  const rows = items.slice((page - 1) * 8, page * 8).map((i) => ({ id: 'prod|' + i.product_id, title: i.name, description: i.qty + ' × ' + money(i.unit_price) + ' = ' + money(i.line_total) }));
  if (page < pages) rows.push({ id: 'edit|' + (page + 1), title: '➡️ More items', description: '' });
  rows.push({ id: 'cart', title: '🧾 Back to order', description: 'Total ' + money(cartTotal()) });
  return list('Edit cart', 'Tap an item to change its quantity or remove it.', 'Choose item', rows, 'Page ' + page + ' of ' + pages);
};

// ---- actions
switch (it.cmd) {
  case 'unregistered':
    out.outMessage = text('Sorry, this number is not registered with us. Please contact your distributor to get access.');
    break;
  case 'skip':
    out.action = 'skip';
    break;
  case 'cancel':
    items = [];
    view = { mode: 'categories', category: '', q: '', page: 1, total: 0, catPage: 1, catPages: 1 };
    state = 'IDLE';
    out.outMessage = text('❌ Your order has been cancelled. Send *ORDER* anytime to start a new one.');
    break;
  case 'list':
    out.outMessage = it.mode === 'categories' ? categoriesScreen(it.note) : productListScreen(it.note);
    break;
  case 'product':
    out.outMessage = productScreen();
    break;
  case 'setqty': {
    const qty = Number(it.qty);
    const p = product;
    if (!p) { state = 'SELECTING_PRODUCT'; out.outMessage = text('Sorry, that product is no longer available. Send ORDER to browse again.'); break; }
    if (!(qty >= 0) || qty > MAX_QTY) { state = 'ENTERING_QUANTITY'; currentProductId = p.id; out.outMessage = text('Please send a quantity between 1 and ' + MAX_QTY + '.'); break; }
    const pos = items.findIndex((i) => String(i.product_id) === String(p.id));
    let note;
    if (qty === 0) {
      if (pos >= 0) items.splice(pos, 1);
      note = '🗑 Removed *' + p.name + '*.';
    } else {
      if (pos < 0 && items.length >= MAX_CART_LINES) { out.outMessage = text('One order can have at most ' + MAX_CART_LINES + ' different products. Send CART to place this order first.'); break; }
      const line = { product_id: p.id, name: p.name, unit: p.unit || 'Piece', qty: qty, unit_price: Number(p.price || 0), line_total: round2(Number(p.price || 0) * qty) };
      if (pos >= 0) items[pos] = line; else items.push(line);
      note = '✅ *' + p.name + '* × ' + qty + ' = ' + money(line.line_total);
    }
    out.outMessage = buttons(note + '\n\n' + cartLine(),
      [{ id: 'back', title: '➕ Add more' }, { id: 'cart', title: '🛒 View cart' }, { id: 'menu|1', title: '📂 Categories' }]);
    state = 'SELECTING_PRODUCT';
    break;
  }
  case 'cart':
    out.outMessage = cartScreen();
    break;
  case 'editcart':
    out.outMessage = editCartScreen();
    break;
  case 'confirm': {
    if (!items.length) { out.outMessage = cartScreen(); break; }
    const t = cartTotal();
    out.action = 'place_order';
    state = 'IDLE';
    out.orderItems = items;
    out.total = t;
    out.invoiceBody = 'Shop: ' + (ctx.shop_name || '') + (ctx.owner_name ? ' (' + ctx.owner_name + ')' : '') +
      '\nPhone: +' + msg.from + (ctx.address ? '\nAddress: ' + ctx.address : '') + '\n\n' +
      items.map((i, n) => (n + 1) + '. ' + i.name + ' x ' + i.qty + ' @ ' + money(i.unit_price) + ' = ' + money(i.line_total)).join('\n') +
      '\n\nTotal: ' + money(t);
    items = [];
    break;
  }
  default:
    out.outMessage = state === 'IDLE'
      ? buttons('👋 Hello ' + name + '! Ready to place an order?', [{ id: 'menu|1', title: '🛍 Start order' }])
      : text('Sorry, I did not get that. Send ORDER to browse, CART to review, or CANCEL.');
}

out.state = state;
out.currentProductId = currentProductId;
out.sessionCart = { items: items, view: view };
return [{ json: out }];

